from __future__ import annotations


def pricing_html() -> str:
    return '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Lucas plans for secure AI-to-computer execution. Start free and upgrade when you need more Requests, Nodes, or AI connections."><link rel="canonical" href="https://lucasmcp.com/pricing"><title>Lucas Pricing</title><style>*{box-sizing:border-box}body{margin:0;background:#05070d;color:#f5f7ff;font:15px/1.6 Inter,system-ui,-apple-system,Segoe UI,sans-serif}a{color:inherit;text-decoration:none}.wrap{max-width:1180px;margin:auto;padding:0 28px 72px}.nav{height:82px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.08)}.nav img{width:190px;height:50px;object-fit:contain;object-position:left center}.nav-actions{display:flex;gap:10px}.ghost,.primary{display:inline-flex;align-items:center;justify-content:center;min-height:42px;padding:0 16px;border-radius:10px;font-weight:750}.ghost{border:1px solid rgba(255,255,255,.13);color:#d8deed;background:rgba(255,255,255,.035)}.primary{background:linear-gradient(110deg,#6473f4,#5969e9);color:#fff;box-shadow:0 12px 36px rgba(86,103,235,.2)}.hero{text-align:center;padding:86px 0 52px}.eyebrow{display:inline-block;font-size:11px;font-weight:800;letter-spacing:.17em;color:#8a96b0}.hero h1{font-size:clamp(46px,6vw,76px);line-height:1;letter-spacing:-.055em;margin:18px 0}.hero p{max-width:680px;margin:0 auto;color:#99a4bb;font-size:18px}.plans{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.card{position:relative;background:linear-gradient(180deg,rgba(16,21,34,.96),rgba(9,12,21,.96));border:1px solid rgba(255,255,255,.1);border-radius:18px;padding:28px;min-height:430px;display:flex;flex-direction:column}.card.hot{border-color:#6d7cff;box-shadow:0 0 0 1px rgba(109,124,255,.2),0 26px 70px rgba(65,79,195,.16)}.tag{position:absolute;right:18px;top:18px;font-size:10px;letter-spacing:.1em;color:#bfc7ff;border:1px solid rgba(109,124,255,.4);padding:5px 8px;border-radius:999px;background:rgba(109,124,255,.09)}.plan{font-size:24px;font-weight:800}.price{font-size:42px;font-weight:850;letter-spacing:-.04em;margin:12px 0 5px}.price small{font-size:14px;color:#8e99b0;font-weight:650}.desc{color:#8f9ab1;min-height:50px}.features{list-style:none;padding:0;margin:20px 0 28px;display:grid;gap:11px;color:#d8deea}.features li:before{content:'✓';color:#70dfa9;margin-right:9px}.card .primary,.card .ghost{margin-top:auto;width:100%}.expansion{margin-top:20px;padding:26px 28px;border:1px solid rgba(255,255,255,.1);border-radius:18px;background:linear-gradient(110deg,rgba(95,109,240,.12),rgba(46,176,220,.06));display:grid;grid-template-columns:1fr auto;align-items:center;gap:24px}.expansion h2{margin:0 0 6px;font-size:24px}.expansion p{margin:0;color:#98a3b9}.expansion strong{font-size:28px}.note{text-align:center;color:#7f8aa1;font-size:13px;margin-top:24px}.faq{margin-top:72px}.faq h2{text-align:center;font-size:34px}.faq-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.faq-item{padding:20px;border-top:1px solid rgba(255,255,255,.1);color:#919cb2}.faq-item b{display:block;color:#eef1f8;margin-bottom:8px}@media(max-width:820px){.plans,.faq-grid{grid-template-columns:1fr}.expansion{grid-template-columns:1fr}.nav-actions .ghost{display:none}.hero{padding-top:58px}.card{min-height:0}}</style></head><body><div class="wrap"><nav class="nav"><a href="/"><img src="/assets/lucas-logo-horizontal-white.png" alt="Lucas"></a><div class="nav-actions"><a class="ghost" href="/">Home</a><a class="primary" href="/dashboard">Open Dashboard</a></div></nav><section class="hero"><div class="eyebrow">SIMPLE, PREDICTABLE PRICING</div><h1>Start free. Scale when you need it.</h1><p>One Lucas account is for one person. Choose the plan that fits your workload, then expand Pro+ without changing your setup.</p></section><section class="plans"><article class="card"><div class="plan">Free</div><div class="price">$0</div><p class="desc">For trying Lucas and light personal workflows.</p><ul class="features"><li>1,000 Requests / month</li><li>1 Node</li><li>1 AI account</li><li>Core Lucas execution</li></ul><a class="ghost" href="/dashboard">Get started</a></article><article class="card"><div class="plan">Pro</div><div class="price">$9.99 <small>/ month</small></div><p class="desc">For regular personal automation on multiple computers.</p><ul class="features"><li>25,000 Requests / month</li><li>3 Nodes</li><li>1 AI account</li><li>Full Lucas execution</li></ul><a class="primary" href="/billing?select=pro">Choose Pro</a></article><article class="card hot"><span class="tag">BEST VALUE</span><div class="plan">Pro+</div><div class="price">$19.99 <small>/ month</small></div><p class="desc">For heavier workflows and users who need expandable capacity.</p><ul class="features"><li>100,000 Requests / month</li><li>6 Nodes</li><li>3 AI accounts</li><li>Expansion Pack access</li></ul><a class="primary" href="/billing?select=pro_plus">Choose Pro+</a></article></section><section class="expansion"><div><h2>Expansion Pack</h2><p>Pro+ only · +100,000 Requests · +6 Nodes · +1 AI account per pack</p></div><strong>$14.99 <small>/ month</small></strong></section><p class="note">Only actual Lucas Node tool operations count as Requests. Heartbeats, reconnects, dashboard refreshes, authentication, and internal checks do not consume Requests.</p><section class="faq"><h2>Good to know</h2><div class="faq-grid"><div class="faq-item"><b>Can I share one account?</b>No. One Lucas account is intended for one person.</div><div class="faq-item"><b>Who can buy Expansion Packs?</b>Expansion Packs are available only to Pro+ subscribers.</div><div class="faq-item"><b>What happens at the limit?</b>Your data stays intact. Upgrade or add capacity to continue new billable operations.</div></div></section></div></body></html>'''


def dashboard_billing_html() -> str:
    return '''<div id="billing" class="view hidden"><div class="top"><div><h2>Plan & Billing</h2><p class="muted">Manage your Lucas plan, usage limits, and Stripe billing.</p></div><div class="toolbar" style="margin:0"><a class="btn secondary" style="text-decoration:none" href="/pricing">View public pricing</a><button id="billingManage" class="btn secondary" onclick="billingPortal()">Manage Billing</button></div></div><div id="billingNotice" class="card hidden" style="margin-bottom:16px"></div><div id="billingError" class="error hidden"></div><div class="card" style="margin-bottom:16px"><div style="display:flex;justify-content:space-between;align-items:center;gap:14px;flex-wrap:wrap"><div><div class="muted">Current plan</div><div id="billingPlan" class="metric">Loading…</div><div id="billingRenew" class="muted"></div></div><div id="billingPrice" style="font-size:22px;font-weight:750"></div></div></div><div class="grid" style="margin-bottom:22px"><div class="card"><div class="muted">Requests</div><div id="billingRequests" class="metric">—</div><div id="billingRequestsBar" style="height:7px;background:#eef1f5;border-radius:999px;margin-top:12px;overflow:hidden"><i style="display:block;height:100%;width:0;background:#155eef"></i></div></div><div class="card"><div class="muted">Nodes</div><div id="billingNodes" class="metric">—</div></div><div class="card"><div class="muted">AI accounts</div><div id="billingAi" class="metric">—</div></div></div><div class="top" style="margin-bottom:14px"><div><h3 style="margin-bottom:4px">Plans</h3><div class="muted">Upgrade anytime. Expansion Packs are Pro+ only.</div></div></div><div class="grid" style="margin-bottom:16px"><div id="billingCardFree" class="card"><h3>Free · $0</h3><p class="muted">1,000 Requests · 1 Node · 1 AI account</p><button class="btn secondary" disabled>Free plan</button></div><div id="billingCardPro" class="card"><h3>Pro · $9.99/mo</h3><p class="muted">25,000 Requests · 3 Nodes · 1 AI account</p><button id="billingChoosePro" class="btn primary" onclick="billingCheckout('pro')">Choose Pro</button></div><div id="billingCardProPlus" class="card"><h3>Pro+ · $19.99/mo</h3><p class="muted">100,000 Requests · 6 Nodes · 3 AI accounts</p><button id="billingChooseProPlus" class="btn primary" onclick="billingCheckout('pro_plus')">Choose Pro+</button></div></div><div class="card"><div style="display:flex;justify-content:space-between;align-items:center;gap:14px;flex-wrap:wrap"><div><h3 style="margin-bottom:5px">Expansion Pack · $14.99/mo</h3><p class="muted" style="margin:0">Pro+ only · +100,000 Requests · +6 Nodes · +1 AI account per pack</p></div><div id="billingExpansion"></div></div></div></div><script>window.billingSelectHandled=false;window.billingApi=async function(url,opt={}){const r=await fetch(url,{credentials:'include',headers:{'Content-Type':'application/json',...(opt.headers||{})},...opt});let d={};try{d=await r.json()}catch{}if(r.status===401){location='/dashboard';return null}if(!r.ok)throw new Error(d.error||('Request failed: '+r.status));return d};window.billingShowError=function(err){const box=document.getElementById('billingError');if(!box)return;box.textContent=err?.message||String(err);box.classList.remove('hidden')};window.billingNotice=function(text,kind='info'){const box=document.getElementById('billingNotice');if(!box)return;box.textContent=text;box.classList.remove('hidden');box.style.background=kind==='success'?'#ecfdf3':'#eff4ff';box.style.color=kind==='success'?'#027a48':'#344054'};window.loadBillingView=async function(){try{billingError.classList.add('hidden');const s=await billingApi('/api/billing/summary');if(!s)return;state.billing=s;billingPlan.textContent=s.plan_name+(s.expansion_quantity?' + '+s.expansion_quantity+' Pack'+(s.expansion_quantity===1?'':'s'):'');billingRenew.textContent=s.renewal_at?'Renews '+new Date(s.renewal_at*1000).toLocaleDateString():'';billingPrice.textContent=s.monthly_price?'$'+Number(s.monthly_price).toFixed(2)+'/mo':'';billingRequests.textContent=s.requests_used.toLocaleString()+' / '+s.request_limit.toLocaleString();billingNodes.textContent=s.nodes_used+' / '+s.node_limit;billingAi.textContent=s.ai_accounts_used+' / '+s.ai_account_limit;const pct=Math.min(100,Math.round((s.requests_used/Math.max(1,s.request_limit))*100));billingRequestsBar.querySelector('i').style.width=pct+'%';billingManage.disabled=!s.has_customer;[billingCardFree,billingCardPro,billingCardProPlus].forEach(x=>{x.style.outline='';x.style.boxShadow=''});const active=s.plan==='pro'?billingCardPro:(s.plan==='pro_plus'?billingCardProPlus:billingCardFree);active.style.outline='2px solid #84adff';active.style.boxShadow='0 0 0 3px #d1e0ff';billingChoosePro.textContent=s.plan==='pro'?'Current Plan':'Choose Pro';billingChoosePro.disabled=s.plan==='pro';billingChooseProPlus.textContent=s.plan==='pro_plus'?'Current Plan':'Choose Pro+';billingChooseProPlus.disabled=s.plan==='pro_plus';billingExpansion.innerHTML=s.can_buy_expansion?'<div class="toolbar" style="margin:0"><span class="muted">Current: '+s.expansion_quantity+'</span><input id="billingExpansionQty" class="input" type="number" min="1" max="100" value="1" style="width:80px"><button class="btn primary" onclick="billingAddExpansion()">Add Pack</button></div>':'<button class="btn primary" onclick="billingCheckout(\'pro_plus\')">Upgrade to Pro+</button>';if(!s.billing_configured){billingNotice('Stripe checkout is not active yet. Your current plan and usage remain available here.')}else if(location.pathname==='/billing/success'){billingNotice('Payment received. Your plan will update as soon as Stripe confirms the subscription.','success')}else if(location.pathname==='/billing/cancel'){billingNotice('Payment was not completed. Your current plan has not changed.')}const selected=new URLSearchParams(location.search).get('select');if(selected&&!billingSelectHandled&&s.billing_configured&&s.plan!==selected){billingSelectHandled=true;await billingCheckout(selected)}}catch(err){billingShowError(err)}};window.billingCheckout=async function(plan){try{const d=await billingApi('/api/billing/checkout',{method:'POST',body:JSON.stringify({plan})});if(d?.url)location=d.url}catch(err){billingShowError(err)}};window.billingAddExpansion=async function(){try{const q=Math.max(1,+document.getElementById('billingExpansionQty').value||1);const d=await billingApi('/api/billing/expansion',{method:'POST',body:JSON.stringify({quantity:q})});if(d?.url)location=d.url}catch(err){billingShowError(err)}};window.billingPortal=async function(){try{const d=await billingApi('/api/billing/portal',{method:'POST'});if(d?.url)location=d.url}catch(err){billingShowError(err)}}</script>'''
